BEGIN;
--
-- Create model EpochReadinessEvaluation
--
CREATE TABLE "arena_epochreadinessevaluation" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "evaluation_key" varchar(200) NOT NULL UNIQUE, "policy_key" varchar(64) NOT NULL, "policy_version" integer NOT NULL CHECK ("policy_version" >= 0), "cutoff_at" timestamp with time zone NOT NULL, "evaluator_version" varchar(100) NOT NULL, "status" varchar(16) NOT NULL, "input_digest" varchar(64) NOT NULL, "evidence" jsonb NOT NULL, "blocking_reasons" jsonb NOT NULL, "created_at" timestamp with time zone NOT NULL, "completed_at" timestamp with time zone NULL, "config_version_id" bigint NOT NULL, "epoch_id" bigint NOT NULL, CONSTRAINT "arena_readiness_terminal_time" CHECK ((("completed_at" IS NULL AND "status" = 'RUNNING') OR ("completed_at" IS NOT NULL AND "status" IN ('BLOCKED', 'FAILED', 'COMPLETE')))));
ALTER TABLE "arena_epochreadinessevaluation" ADD CONSTRAINT "arena_epochreadiness_config_version_id_fab1f89f_fk_game_conf" FOREIGN KEY ("config_version_id") REFERENCES "game_config_gameconfigversion" ("id") DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "arena_epochreadinessevaluation" ADD CONSTRAINT "arena_epochreadiness_epoch_id_d1416d7c_fk_arena_eco" FOREIGN KEY ("epoch_id") REFERENCES "arena_economicepoch" ("id") DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX "arena_epochreadinessevaluation_evaluation_key_f7e3db9b_like" ON "arena_epochreadinessevaluation" ("evaluation_key" varchar_pattern_ops);
CREATE INDEX "arena_epochreadinessevaluation_config_version_id_fab1f89f" ON "arena_epochreadinessevaluation" ("config_version_id");
CREATE INDEX "arena_epochreadinessevaluation_epoch_id_d1416d7c" ON "arena_epochreadinessevaluation" ("epoch_id");
CREATE INDEX "arena_readiness_latest" ON "arena_epochreadinessevaluation" ("epoch_id", "id" DESC);
COMMIT;
